import{_ as i,o as a,c as n,a2 as t}from"./chunks/framework.CqGPl1zp.js";const e="/newx-doc/assets/%E8%A1%A8%E5%85%B3%E7%B3%BB.BaFhmApI.svg",p="/newx-doc/assets/%E5%B7%A5%E4%BD%9C%E8%AE%B0%E5%BD%95%E7%8A%B6%E6%80%81%E6%A0%8F.B9zJYHKi.png",l="/newx-doc/assets/%E5%B7%A5%E4%BD%9C%E8%AE%B0%E5%BD%95%E5%88%97%E8%A1%A8.CYF5sNY6.png",F=JSON.parse('{"title":"【生产】工作记录","description":"","frontmatter":{},"headers":[],"relativePath":"mes/pro/work-record.md","filePath":"mes/pro/work-record.md","lastUpdated":null}'),h={name:"mes/pro/work-record.md"};function k(r,s,d,o,E,c){return a(),n("div",null,[...s[0]||(s[0]=[t('<h1 id="【生产】工作记录" tabindex="-1">【生产】工作记录 <a class="header-anchor" href="#【生产】工作记录" aria-label="Permalink to &quot;【生产】工作记录&quot;">​</a></h1><p>工作记录模块，由 <code>yudao-module-mes</code> 后端模块的 <code>pro.workrecord</code> 包实现，用于管理车间操作人员与工作站之间的<strong>上工/下工绑定关系</strong>。</p><ul><li>操作人员进入产线前，通过【上工】操作将自己绑定到某个工作站，表示&quot;我现在在这个工位上工作&quot;；离开时通过【下工】操作标记为已下工状态（快照表保留上一次工作站信息，不会清空）。</li><li>系统会记录每一次上下工事件，形成完整的人员出勤流水，便于管理人员追踪哪些人在哪些工位上工作过、何时上工/下工。</li></ul><p>模块采用<strong>快照 + 流水</strong>的双表架构：</p><ul><li><strong>当前绑定状态</strong>：快照表，每个用户最多一条记录，反映该用户最近一次操作的工作站及当前上工/下工状态。下工后 <code>workstation_id</code> <strong>不会被清空</strong>，仍保留上一次工作站信息。</li><li><strong>上下工记录流水</strong>：流水表，记录每一次上工/下工操作，形成完整的历史时间线。</li></ul><p>本文涉及表如下图所示：</p><p><img src="'+e+'" alt="工作记录模块"></p><h2 id="_1-当前绑定状态-快照表" tabindex="-1">1. 当前绑定状态（快照表） <a class="header-anchor" href="#_1-当前绑定状态-快照表" aria-label="Permalink to &quot;1. 当前绑定状态（快照表）&quot;">​</a></h2><p>当前绑定状态表用于存储每个用户<strong>最新的</strong>工作站绑定快照，由 MesProWorkRecordServiceImpl 内部维护，不由前端直接增删改。</p><h3 id="_1-1-表结构" tabindex="-1">1.1 表结构 <a class="header-anchor" href="#_1-1-表结构" aria-label="Permalink to &quot;1.1 表结构&quot;">​</a></h3><blockquote><p>省略 creator/create_time/updater/update_time/deleted/tenant_id 等通用字段</p></blockquote><div class="language-SQL vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> `</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mes_pro_work_record</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">` (</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AUTO_INCREMENT COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `user_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;用户编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `workstation_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;工作站编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `type`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> tinyint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;当前状态（1=上工 2=下工）&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `clock_in_time`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> datetime</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;上工时间&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `clock_out_time`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> datetime</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;下工时间&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `remark`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DEFAULT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;备注&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  UNIQUE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `uk_user_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`user_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) ENGINE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">InnoDB COMMENT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;MES 当前绑定状态快照&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>① <code>user_id</code> 关联 <code>system_users</code> 表的 <code>id</code> 字段，通过唯一索引 <code>uk_user_id</code> 保证每个用户最多一条记录。首次上工时插入，后续上工/下工均为更新。</p><p>② <code>workstation_id</code> 关联 <code>mes_md_workstation</code> 表的 <code>id</code> 字段，记录用户最近一次操作的工作站，详见 <a href="./../md/workshop">《【基础】车间设置、工作站设置》</a>。<strong>下工时不会清空该字段</strong>，仅更新 <code>type</code> 和 <code>clock_out_time</code>。</p><p>③ <code>type</code> 为当前状态，枚举 MesProWorkRecordTypeEnum（1=上工，2=下工）。上工时设置为 1，下工时设置为 2。</p><p>④ <code>clock_in_time</code> 和 <code>clock_out_time</code> 记录最近一次上工/下工的时间。<strong>上工时</strong>系统更新 <code>clock_in_time</code>，<code>clock_out_time</code> 保留上一次下工时间不变；<strong>下工时</strong>系统写入 <code>clock_out_time</code>。</p><h2 id="_2-上下工记录流水" tabindex="-1">2. 上下工记录流水 <a class="header-anchor" href="#_2-上下工记录流水" aria-label="Permalink to &quot;2. 上下工记录流水&quot;">​</a></h2><p>上下工记录流水，由 MesProWorkRecordController 提供接口。每一次上工/下工操作都会在流水表中追加一条记录，构成完整的历史时间线。</p><h3 id="_2-1-表结构" tabindex="-1">2.1 表结构 <a class="header-anchor" href="#_2-1-表结构" aria-label="Permalink to &quot;2.1 表结构&quot;">​</a></h3><blockquote><p>省略 creator/create_time/updater/update_time/deleted/tenant_id 等通用字段</p></blockquote><div class="language-SQL vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> `</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mes_pro_work_record_log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">` (</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AUTO_INCREMENT COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `user_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;用户编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `workstation_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;工作站编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `type`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> tinyint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;操作类型（1=上工 2=下工）&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `remark`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DEFAULT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;备注&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) ENGINE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">InnoDB COMMENT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;MES 上下工记录流水&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>① <code>user_id</code> 关联 <code>system_users</code> 表的 <code>id</code> 字段，标识执行上工/下工操作的用户。</p><p>② <code>workstation_id</code> 关联 <code>mes_md_workstation</code> 表的 <code>id</code> 字段，标识本次操作关联的工作站，详见 <a href="./../md/workshop">《【基础】车间设置、工作站设置》</a>。</p><p>③ <code>type</code> 为操作类型，枚举 MesProWorkRecordTypeEnum（1=上工，2=下工）。</p><p>上工/下工业务流程</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户A 上工(工作站X) ──→ 快照表：插入/更新为上工状态</span></span>\n<span class="line"><span>                      流水表：追加一条「上工」记录</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>用户A 下工 ──────────→ 快照表：更新为下工状态</span></span>\n<span class="line"><span>                      流水表：追加一条「下工」记录</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>用户A 再次上工(工作站Y) → 快照表：更新工作站为Y，状态为上工</span></span>\n<span class="line"><span>                        流水表：追加一条「上工」记录</span></span></code></pre></div><ul><li><strong>上工</strong>（<code>clockInWorkRecord</code>）：校验工作站存在 → 校验用户未处于上工状态（防止重复上工）→ 写入上工流水 → 更新快照表（首次则插入，非首次则更新工作站、状态、<code>clock_in_time</code>，<code>clock_out_time</code> 保留不变）。</li><li><strong>下工</strong>（<code>clockOutWorkRecord</code>）：校验用户处于上工状态 → 写入下工流水 → 更新快照表状态为下工，记录 <code>clock_out_time</code>。</li></ul><h3 id="_2-2-管理后台" tabindex="-1">2.2 管理后台 <a class="header-anchor" href="#_2-2-管理后台" aria-label="Permalink to &quot;2.2 管理后台&quot;">​</a></h3><p>对应 [MES 系统 -&gt; 生产管理 -&gt; 工作记录] 菜单，对应 <code>yudao-ui-admin-vue3</code> 项目的 <code>@/views/mes/pro/workrecord</code> 目录。</p><h4 id="我的工作站状态栏" tabindex="-1">我的工作站状态栏 <a class="header-anchor" href="#我的工作站状态栏" aria-label="Permalink to &quot;我的工作站状态栏&quot;">​</a></h4><p>页面顶部有一个横向状态栏（WorkRecordStatusBar.vue），显示当前登录用户的工作站绑定状态：</p><ul><li><strong>已上工</strong>：显示绑定的工作站编码和名称（绿色标签），以及上工时间。右侧提供【下工】按钮，点击后二次确认即可解绑。</li><li><strong>未上工</strong>：显示「当前未上工」（灰色标签）。右侧提供【上工】按钮，点击后弹出工作站选择器，选择目标工作站后点击【确认上工】完成绑定。</li></ul><p>上工/下工操作完成后，状态栏会自动刷新，同时触发下方流水列表重新加载。</p><p><img src="'+p+'" alt="管理后台 - 工作记录状态栏"></p><h4 id="列表" tabindex="-1">列表 <a class="header-anchor" href="#列表" aria-label="Permalink to &quot;列表&quot;">​</a></h4><p>状态栏下方为上下工记录流水列表。支持按用户、工作站、操作类型、操作时间范围等条件搜索。列表展示编号、用户、工作站编码、工作站名称、操作类型（上工/下工）、创建时间等信息。</p><p><img src="'+l+'" alt="管理后台 - 工作记录列表"></p>',37)])])}const y=i(h,[["render",k]]);export{F as __pageData,y as default};
